export const getListComponentFunctionsUrl = (
  organizationId: string,
  componentId: string,
  params?: ListComponentFunctionsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/v2/organizations/${encodeURIComponent(String(organizationId))}/components/${encodeURIComponent(String(componentId))}/functions?${stringifiedParams}`
    : `/api/v2/organizations/${encodeURIComponent(String(organizationId))}/components/${encodeURIComponent(String(componentId))}/functions`;
};

